import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_good_numbers(g_limit=30, xy_limit=25):
    good_numbers = set()

    # g is the GCD, must be >= 2
    for g in range(2, g_limit + 1):
        g_sq = g * g

        # x' and y' must be coprime and x' < y'
        for x_prime in range(1, xy_limit + 1):
            for y_prime in range(x_prime + 1, xy_limit + 1):
                if gcd(x_prime, y_prime) == 1:
                    m = g_sq * (x_prime**2 + y_prime**2)
                    good_numbers.add(m)

    sorted_numbers = sorted(list(good_numbers))
    return sorted_numbers

# We expect the 20th number to be relatively small. 
# Let's start with limits and check the 20th element.
# If the 20th element is far beyond 1000, we increase the limits.
sorted_list = generate_good_numbers(g_limit=10, xy_limit=15)

# Check if we have at least 20 elements
if len(sorted_list) < 20:
    print("Need to increase limits.")
else:
    print(f"The 20th smallest good number is: {sorted_list[19]}")
    print("Top 25 numbers:", sorted_list[:25])
